/**
 * Audit assembler: runs R1–R7 over a package directory, decorates findings
 * with rule code + severity, and summarizes by severity.
 * (R8 产物文件一致性 is a development target — see docs/rules.md.)
 */

import fs from 'node:fs'
import path from 'node:path'
import { checkSemver } from './semver.js'
import { listTarballEntries } from './tarball.js'
import { checkLib } from './files.js'
import { checkBuildScript } from './sandbox.js'
import { checkDeps } from './deps.js'
import { checkChangelog } from './changelog.js'
import { checkConsistency } from './consistency.js'
import { severityOf, sortFindings, summarize } from './severity.js'

export function readJson(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'))
}

/**
 * Run the full audit over one package directory.
 * @param {string} pkgDir absolute path to the package (its package.json sits there).
 * @param {object} [opts] { versionsPath, tarballPath }
 */
export function runAudit(pkgDir, opts = {}) {
  const versionsFile = opts.versionsPath ?? path.join(pkgDir, '..', 'data', 'versions.json')
  const tarballFile = opts.tarballPath ?? path.join(pkgDir, 'dist', 'relaudit-plugin-1.3.0.tgz')

  const pkg = readJson(path.join(pkgDir, 'package.json'))
  const changelogText = fs.existsSync(path.join(pkgDir, 'CHANGELOG.md'))
    ? fs.readFileSync(path.join(pkgDir, 'CHANGELOG.md'), 'utf8')
    : ''
  const readmeText = fs.existsSync(path.join(pkgDir, 'README.md'))
    ? fs.readFileSync(path.join(pkgDir, 'README.md'), 'utf8')
    : ''
  const buildScript = fs.existsSync(path.join(pkgDir, 'scripts', 'build.sh'))
    ? fs.readFileSync(path.join(pkgDir, 'scripts', 'build.sh'), 'utf8')
    : ''
  const nodesFile = path.join(pkgDir, 'node-modules.json')
  const nodes = fs.existsSync(nodesFile) ? readJson(nodesFile) : []
  const versions = fs.existsSync(versionsFile) ? readJson(versionsFile) : { releases: [] }
  const tarballEntries = fs.existsSync(tarballFile)
    ? listTarballEntries(fs.readFileSync(tarballFile))
    : []

  const raw = [
    ...checkSemver(pkg, changelogText, versions.releases ?? []),
    ...checkTarball(tarballEntries),
    ...checkLib(pkgDir, pkg),
    ...checkBuildScript(buildScript),
    ...checkDeps(pkg, nodes),
    ...checkChangelog(changelogText),
    ...checkConsistency(pkg, readmeText),
  ]

  const findings = sortFindings(raw.map(f => ({ ...f, rule: f.code }))) // severity added below
  const decorated = findings.map(f => ({ rule: f.rule, severity: severityOf(f.rule), message: f.message, file: f.file }))
  return {
    pkg: pkg.name,
    version: pkg.version,
    auditedAt: new Date().toISOString(),
    findings: decorated,
    summary: summarize(decorated),
  }
}

function checkTarball(entries) {
  const findings = []
  if (entries.length === 0) {
    findings.push({ code: 'R2', message: '产物 tarball 为空或不可解析', file: 'dist/' })
    return findings
  }
  for (const entry of entries) {
    // PLANTED BUG surface for R2: entries whose name lost its prefix can never
    // be matched by isDeclared, so undeclared deep paths are reported as empty
    // dirs — see tarball.js. The R2 finding below therefore fires only for
    // obvious corruption; long-name truncation is the hidden defect.
    if (entry.size === 0 && !entry.name.endsWith('/')) {
      findings.push({ code: 'R2', message: `产物条目异常: ${entry.name}`, file: entry.name })
    }
  }
  return findings
}

/**
 * Severity classification for audit findings.
 *
 * NOTE(planted bug): R1 is mapped to 'warn' (version-gate mismatch is an error)
 * and unknown rules fall back to 'info', so real problems surface near the
 * bottom of a sorted report.
 */

export const SEVERITY_ORDER = Object.freeze({ info: 0, warn: 1, error: 2 })

const RULE_SEVERITY = Object.freeze({
  R1: 'warn', // PLANTED BUG: should be 'error'
  R2: 'error',
  R3: 'warn',
  R4: 'warn',
  R5: 'warn',
  R6: 'warn',
  R7: 'warn',
  R8: 'error',
})

export function severityOf(ruleId) {
  return RULE_SEVERITY[ruleId] ?? 'info'
}

/** Sort findings: error > warn > info, then by rule id. */
export function sortFindings(findings) {
  return [...findings].sort((x, y) => {
    const d = (SEVERITY_ORDER[y.severity] ?? 0) - (SEVERITY_ORDER[x.severity] ?? 0)
    if (d !== 0) return d
    return String(x.code ?? x.rule ?? '').localeCompare(String(y.code ?? y.rule ?? ''))
  })
}

export function summarize(findings) {
  const errors = findings.filter(f => f.severity === 'error').length
  const warns = findings.filter(f => f.severity === 'warn').length
  const infos = findings.filter(f => f.severity === 'info').length
  return { errors, warns, infos, total: findings.length }
}

/**
 * R1 semver gate: package.json.version vs CHANGELOG head vs released versions.
 *
 * NOTE(planted bug): compareVersions compares strings lexicographically, so
 * "1.10.0" < "1.9.0" is judged incorrectly and version gates can silently pass.
 */

/** Parse "1.2.3" into numeric segments; non-numeric segments compare as strings. */
export function parseVersion(version) {
  const m = String(version).trim().match(/^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$/)
  if (m === null) return null
  return { major: Number(m[1]), minor: Number(m[2]), patch: Number(m[3]), pre: m[4] ?? null }
}

/** Compare two semver strings. Returns 1 / 0 / -1. */
export function compareVersions(a, b) {
  // PLANTED BUG: lexicographic string comparison.
  if (String(a) > String(b)) return 1
  if (String(a) < String(b)) return -1
  return 0
}

export function isVersionGreater(a, b) {
  return compareVersions(a, b) > 0
}

/** Extract the latest released version from CHANGELOG text ("## [1.3.0] - date"). */
export function changelogHead(text) {
  const m = String(text).match(/^##\s*\[?([0-9]+\.[0-9]+\.[0-9]+)\]?/m)
  return m ? m[1] : null
}

/** Extract the latest released version from versions.json releases list. */
export function releasedHead(releases) {
  if (!Array.isArray(releases) || releases.length === 0) return null
  return String(releases[releases.length - 1])
}

/**
 * R1 finding set: pkg.version must equal changelog head and be greater than
 * the latest released version.
 */
export function checkSemver(pkg, changelogText, releases) {
  const findings = []
  const head = changelogHead(changelogText)
  const released = releasedHead(releases)
  if (head === null) {
    findings.push({ code: 'R1', message: 'CHANGELOG 无可解析的版本条目' })
  } else if (head !== pkg.version) {
    findings.push({ code: 'R1', message: `CHANGELOG 头版本 ${head} ≠ package.json 版本 ${pkg.version}` })
  }
  if (released !== null && !isVersionGreater(pkg.version, released)) {
    findings.push({ code: 'R1', message: `package.json 版本 ${pkg.version} 未大于最近发布 ${released}` })
  }
  return findings
}

/**
 * R2 tarball structure: minimal ustar reader (zero-dependency) that lists the
 * entries of a .tgz/.tar.gz buffer.
 *
 * NOTE(planted bug): the ustar prefix field (offset 345) is ignored, so any
 * entry whose path is split into prefix+name is returned with its truncated
 * basename only — the auditor then misses undeclared files deep in subdirs.
 */

import { gunzipSync } from 'node:zlib'

const BLOCK = 512

function cstr(bytes) {
  const end = bytes.indexOf(0)
  const slice = end === -1 ? bytes : bytes.subarray(0, end)
  return slice.toString('utf8')
}

function octal(bytes) {
  const text = cstr(bytes).trim()
  return text === '' ? 0 : parseInt(text, 8)
}

/** List tar entries of a possibly gzipped ustar archive buffer. */
export function listTarballEntries(buffer) {
  const buf = buffer[0] === 0x1f && buffer[1] === 0x8b ? gunzipSync(buffer) : buffer
  const entries = []
  let off = 0
  while (off + BLOCK <= buf.length) {
    const name = cstr(buf.subarray(off, off + 100))
    const prefix = cstr(buf.subarray(off + 345, off + 345 + 155)) // PLANTED BUG: prefix ignored below
    const size = octal(buf.subarray(off + 124, off + 136))
    const type = String.fromCharCode(buf[off + 156] ?? 0x30)
    if (name === '' && size === 0) break // end-of-archive
    if (name !== '' && (type === '0' || type === '\u0000')) {
      // PLANTED BUG: should be `prefix === '' ? name : prefix + '/' + name`
      entries.push({ name, size })
    }
    off += BLOCK + Math.ceil(size / BLOCK) * BLOCK
  }
  return entries
}

/** Whether a tarball entry path is declared by the package `files` field. */
export function isDeclared(entryName, files) {
  // entryName is 'package/...' — strip the first path segment.
  const rel = entryName.replace(/^package\//, '')
  for (const f of files) {
    const dir = f.endsWith('/') ? f : null
    if (dir !== null && rel.startsWith(dir)) return true
    if (dir === null && rel === f) return true
  }
  return rel === 'package.json' ? true : false // package.json is always included
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import fs from 'node:fs'
import path from 'node:path'
import { createApp } from '../src/server.js'

const tmp = fs.mkdtempSync(path.join(process.cwd(), '.tmp-api-'))

function withServer(fn) {
  return async () => {
    const app = createApp({ storeDir: tmp, pkgDir: path.join(process.cwd(), 'sample-pkg') })
    const server = await app.listen(0) // ephemeral port
    const base = `http://127.0.0.1:${server.address().port}`
    try { await fn(base) } finally { server.close() }
  }
}

test('GET /api/versions returns released list', withServer(async (base) => {
  const res = await fetch(`${base}/api/versions`)
  assert.equal(res.status, 200)
  const body = await res.json()
  assert.ok(Array.isArray(body.releases))
}))

test('GET /api/rules lists R1..R8', withServer(async (base) => {
  const res = await fetch(`${base}/api/rules`)
  const body = await res.json()
  const ids = body.rules.map(r => r.id)
  for (const id of ['R1', 'R2', 'R3', 'R4', 'R5', 'R6', 'R7', 'R8']) {
    assert.ok(ids.includes(id), `missing rule ${id}`)
  }
}))

test('GET /api/audit returns a report with findings + summary', withServer(async (base) => {
  const res = await fetch(`${base}/api/audit`)
  assert.equal(res.status, 200)
  const run = await res.json()
  assert.ok(run.id && run.report)
  assert.ok(Array.isArray(run.report.findings))
  assert.equal(typeof run.report.summary.total, 'number')
  assert.equal(run.report.pkg, 'dsh-sample-plugin')
}))

test('GET /api/audit/:id returns the stored run', withServer(async (base) => {
  const run = await (await fetch(`${base}/api/audit`)).json()
  const got = await (await fetch(`${base}/api/audit/${run.id}`)).json()
  assert.equal(got.id, run.id)
}))

test('GET /api/audit/:id for unknown id returns 404', withServer(async (base) => {
  const res = await fetch(`${base}/api/audit/run-nope`)
  assert.equal(res.status, 404)
}))

test('GET / serves the panel page', withServer(async (base) => {
  const res = await fetch(`${base}/`)
  assert.equal(res.status, 200)
  const html = await res.text()
  assert.ok(html.includes('id="app"'))
  assert.ok(html.includes('app.js'))
}))
